INSERT INTO `assets` VALUES (1,'papa/magnific_create-character-sheet-fo_2937679281','familie',NULL,'assets/familie/796d3705d522-magnific_create-character-sheet-fo_2937679281_aaf6bab5.png','/manus-storage/assets/familie/796d3705d522-magnific_create-character-sheet-fo_2937679281_aaf6bab5.png','Vollständiges animiertes Character-Sheet eines kahlköpfigen, bärtigen Mannes namens „Toni\" im Pixar-Stil, der ein blau-kariertes Flanellhemd und Jeans trägt. Das Sheet zeigt Ganzkörper-Ansichten (frontal, Rücken, Seite), sechs Gesichtsausdrücke (fröhlich, überrascht, wütend, entspannt u. a.), eine Fahrszene sowie zugehöriges Gear (Autoschlüssel, Thermobecher, Trucker-Cap). Ein Infozettel beschreibt ihn als „Dad / Driver\" mit dem Motto „Adventure Mode: Always On\".','[\"charakterbogen\", \"papa\", \"familie\", \"pixar-stil\", \"animiert\", \"fahrer\", \"kahlköpfig\", \"flanellhemd\"]','2026-05-07 10:46:05','2026-05-08 10:47:46',1,1,'frontal portrait','Blau-kariertes Flanellhemd, Jeans, braune Arbeitsschuhe, Ledergürtel','neutraler Hintergrund (Character-Sheet-Layout mit weißem/beigem Hintergrund)','playful','[\"#3a5f9e\", \"#c47a3a\", \"#f0e8d8\"]','796d3705d522b74a275ca69ec7263042e921ba6693a6b06b110bbbb503b9de4f','klarekante-style/papa/magnific_create-character-sheet-fo_2937679281.png',1,97,'approved','[{\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"expression_happy\", \"description\": \"Toni mit breitem, strahlendem Lachen und aufgerissenen Augen – volle Begeisterung.\"}, {\"axis\": \"pose\", \"mood\": \"surprised\", \"name\": \"expression_surprised\", \"description\": \"Toni mit weit aufgerissenen Augen und offenem Mund – totale Überraschung.\"}, {\"axis\": \"pose\", \"mood\": \"angry\", \"name\": \"expression_angry\", \"description\": \"Toni mit zusammengezogenen Brauen und zusammengebissenen Zähnen – deutlich verärgert.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"expression_laughing\", \"description\": \"Toni lacht schallend mit weit geöffnetem Mund – ausgelassen und herzlich.\"}, {\"axis\": \"pose\", \"mood\": \"neutral\", \"name\": \"expression_relaxed\", \"description\": \"Toni mit entspanntem, ruhigem Gesichtsausdruck und leichtem Lächeln.\"}, {\"axis\": \"pose\", \"mood\": \"confident\", \"name\": \"expression_smug\", \"description\": \"Toni mit selbstgefälligem Grinsen und leicht hochgezogener Augenbraue.\"}, {\"axis\": \"environment-moment\", \"mood\": \"happy\", \"name\": \"driving_scene\", \"description\": \"Toni am Steuer eines vollbeladenen Familien-SUVs mit Kindern, Hund und Katze – Roadtrip-Stimmung.\"}]'),(2,'papa/magnific_create-character-sheet-fo_2937584202','familie',NULL,'assets/familie/e810abded2b0-magnific_create-character-sheet-fo_2937584202_39da1b37.png','/manus-storage/assets/familie/e810abded2b0-magnific_create-character-sheet-fo_2937584202_39da1b37.png','Ein professionelles Charakter-Referenzblatt eines animierten, kahlköpfigen Mannes mit rotem Vollbart im Pixar-ähnlichen 3D-Stil. Das Sheet zeigt Ausdrucksvariationen, ein 360°-Turnaround, eine Farbpalette sowie sechs Outfit-Variationen (Road Trip, Camping, Kochen, Chillen, Winter, Arbeit) mit passenden Accessoires. Der Charakter ist ein gutmütiger, kräftiger Familienvater mit großem Lachen und einem Daumen-hoch-Gestus als Hauptpose.','[\"charakter-sheet\", \"papa\", \"familie\", \"3D-animation\", \"pixar-stil\", \"kahlköpfig\", \"vollbart\", \"outfit-variationen\"]','2026-05-07 10:46:05','2026-05-08 10:47:56',1,1,'frontal portrait','Kariertes Flanellhemd (blau/braun), Jeans, braune Arbeitsschuhe – Haupt-Outfit; Variationen: Hawaiihemd, Wanderausrüstung, Grillschürze, Schlafanzug, Winterjacke, Werkzeuggürtel','neutraler cremefarbener Hintergrund (Character-Sheet-Layout)','happy','[\"#2b4a8c\", \"#8b4513\", \"#f5e6d0\"]','e810abded2b09af86467f4d931384213f163bb92f6d525eeb8934da1ef529838','klarekante-style/papa/magnific_create-character-sheet-fo_2937584202.png',1,98,'approved','[{\"axis\": \"outfit\", \"mood\": \"happy\", \"name\": \"road_trip\", \"season\": \"summer\", \"description\": \"Dad im bunten Blumenhemd, Cargo-Shorts und Sandalen, hält \'#1 Dad\'-Kaffeebecher und strahlt breites Lachen aus.\"}, {\"axis\": \"outfit\", \"mood\": \"happy\", \"name\": \"camping\", \"season\": \"summer\", \"description\": \"Dad in olivfarbenem Hoodie und kurzen Hosen mit großem Wanderrucksack und Wanderstock, abenteuerlustiger Gesichtsausdruck.\"}, {\"axis\": \"outfit\", \"mood\": \"happy\", \"name\": \"cooking\", \"description\": \"Dad in brauner \'Grill Master\'-Schürze und Flip-Flops, hält Grillwender hoch und lacht begeistert.\"}, {\"axis\": \"outfit\", \"mood\": \"neutral\", \"name\": \"chilled\", \"description\": \"Dad im gemütlichen grauen Hoodie und karierten Pyjamahosen mit \'Nap Mode\'-Becher, total entspannter Ausdruck.\"}, {\"axis\": \"outfit\", \"mood\": \"happy\", \"name\": \"winter\", \"season\": \"winter\", \"description\": \"Dad in warmer brauner Shearling-Jacke, kariertem Schal und Wollmütze, breit grinsend.\"}, {\"axis\": \"outfit\", \"mood\": \"happy\", \"name\": \"work_mode\", \"description\": \"Dad in blauem Jeanshemd mit Werkzeuggürtel, hält Akkubohrmaschine – der heimwerkende Familienvater im Arbeitseinsatz.\"}]'),(3,'papa/magnific_create-character-sheet-fo_2937672355','familie',NULL,'assets/familie/1d58f0d7ef5b-magnific_create-character-sheet-fo_2937672355_26a072cc.png','/manus-storage/assets/familie/1d58f0d7ef5b-magnific_create-character-sheet-fo_2937672355_26a072cc.png','Offizielles Charakter-Sheet eines animierten, karikaturhaften Vaters im Pixar-/3D-Cartoon-Stil: kahlköpfiger, vollbärtiger, kräftig gebauter Mann mit breitem Lachen und ausdrucksstarken Augen. Das Sheet zeigt den Charakter in mehreren Outfit-Varianten (Road Trip, Beach Day, Work Mode, Cozy Night, Winter Time), verschiedenen Gesichtsausdrücken sowie einer 360°-Rundumsicht im Haupt-Outfit – kariertes blaues Flanellhemd, Jeans und Arbeitsschuhe, mit einer „#1 Dad\"-Tasse in der Hand.','[\"Papa\", \"Charakter-Sheet\", \"Cartoon\", \"Pixar-Stil\", \"Familie\", \"Vater\", \"3D-Animation\", \"Outfit-Varianten\"]','2026-05-07 10:46:06','2026-05-07 15:02:59',1,1,'frontal portrait','Kariertes blaues Flanellhemd, Jeans, brauner Ledergürtel, Arbeitsschuhe; weitere Outfits: Reise-, Strand-, Arbeits-, Pyjama- und Winterkleidung','Neutraler cremefarbener Skizzen-/Storyboard-Hintergrund','happy','[\"#3a5fa0\", \"#c87941\", \"#f5ede0\"]','1d58f0d7ef5b209c3af15208c2a7104e6d646a74a2b6811dd29ee90b2217d763','klarekante-style/papa/magnific_create-character-sheet-fo_2937672355.png',1,98,'approved',NULL),(4,'papa/magnific_create-character-sheet-fo_2937679166','familie',NULL,'assets/familie/282c898bbb84-magnific_create-character-sheet-fo_2937679166_fb4496e8.png','/manus-storage/assets/familie/282c898bbb84-magnific_create-character-sheet-fo_2937679166_fb4496e8.png','Vollständiges Charakter-Design-Sheet eines animierten, kahlköpfigen Mannes namens „Toni – Adventure Dad. Full-Time Legend.\" im Pixar/Disney-3D-Stil. Das Sheet zeigt den kräftig gebauten, rotbärtigen Charakter in verschiedenen Posen (Frontal, Seite, Rücken), Gesichtsausdrücken (glücklich, überrascht, traurig, wütend) sowie einer Fahrszene; ergänzt durch Charakter-Items wie einen Kaffeebecher mit Aufschrift „Adventure Mode: Always On\" und eine Schlafrolle. Der Hintergrund ist cremeweiß mit handgezeichneten Crayon-Akzenten in Blau, Rot und Pink.','[\"charaktersheet\", \"animiert\", \"pixar-stil\", \"familie\", \"papa\", \"kahlkopf\", \"holzfällerhemd\", \"road-trip\"]','2026-05-07 10:46:07','2026-05-08 10:47:29',1,1,'frontal portrait','Blaues Karomuster-Flanellhemd über schwarzem T-Shirt, Jeans, braune Arbeitsstiefel, Ledergürtel','neutraler, cremefarbener Studiohintergrund mit handgezeichneten Crayon-Dekorelementen','playful','[\"#2b4a7a\", \"#c0622a\", \"#f5f0e8\"]','282c898bbb8487d0e72b0b1d55f016ebd6664829783bb98b5758022ccf2d5b40','klarekante-style/papa/magnific_create-character-sheet-fo_2937679166.png',1,97,'approved','[{\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"expression_happy\", \"description\": \"Toni mit breitem, strahlendem Lachen und großen Augen – fröhlicher Gesichtsausdruck.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"expression_laughing\", \"description\": \"Toni lacht laut und offen, Mund weit aufgerissen – überschwängliche Freude.\"}, {\"axis\": \"pose\", \"mood\": \"surprised\", \"name\": \"expression_surprised\", \"description\": \"Toni mit weit aufgerissenen Augen und leicht offenem Mund – überraschter Gesichtsausdruck.\"}, {\"axis\": \"pose\", \"mood\": \"sad\", \"name\": \"expression_sad\", \"description\": \"Toni mit heruntergezogenen Mundwinkeln und trübem Blick – trauriger Gesichtsausdruck.\"}, {\"axis\": \"pose\", \"mood\": \"angry\", \"name\": \"expression_angry\", \"description\": \"Toni mit zusammengezogenen Brauen und hartem Blick – wütender Gesichtsausdruck.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"hero_pose_thumbsup\", \"description\": \"Toni in voller Körpergröße, kariertes Flanellhemd und Jeans, gibt lachend einen Daumen hoch – zentrale Heldenpose.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"driving_scene\", \"description\": \"Toni am Steuer seines Autos, breit grinsend, beide Hände am Lenkrad – dynamische Fahrszene.\"}]'),(6,'papa/magnific_create-character-sheet-fo_2937679364','familie',NULL,'assets/familie/3ab929ba6c3b-magnific_create-character-sheet-fo_2937679364_45820b6a.png','/manus-storage/assets/familie/3ab929ba6c3b-magnific_create-character-sheet-fo_2937679364_45820b6a.png','Vollständiges Charakter-Referenzblatt eines animierten, kräftigen Mannes namens „Toni\" im Pixar/Disney-3D-Cartoon-Stil. Die Figur ist kahlköpfig mit rotem Vollbart, trägt ein blau-kariertes Flanellhemd, Jeans und braune Arbeitsstiefel, und hält eine „Best Dad\"-Kaffeetasse. Das Sheet zeigt diverse Gesichtsausdrücke (fröhlich, nachdenklich, besorgt, wütend), Ganzkörper-Ansichten von vorne, der Seite und hinten, sowie Szenen-Posen (Autofahren, Karte lesen, Daumen hoch) und ein beladenes Abenteuer-Auto.','[\"charakter-sheet\", \"familie\", \"papa\", \"cartoon\", \"pixar-stil\", \"kahlköpfig\", \"flanellhemd\", \"roadtrip\"]','2026-05-07 10:46:18','2026-05-07 10:46:18',1,1,'frontal portrait','Blaues Karoflanellhemd über grauem T-Shirt, dunkle Jeans mit Ledergürtel, braune Schnürstiefel','Neutraler, cremefarbener Hintergrund mit handgezeichneten Notizzetteln und Farbpaletten-Dots','happy','[\"#3b5a8a\", \"#c07840\", \"#2e2e2e\"]','3ab929ba6c3bdcdf8e4f8a5674ab25239d214d2edbe949d848106bd0c1527514','klarekante-style/papa/magnific_create-character-sheet-fo_2937679364.png',1,97,'approved',NULL),(11,'magnific_create-character-sheet-fo_2924197228','familie',NULL,'assets/uploads/1778160306666-magnific_create-character-sheet-fo_2924197228_8192c798.png','/manus-storage/assets/uploads/1778160306666-magnific_create-character-sheet-fo_2924197228_8192c798.png','Vollständiges Character-Sheet eines animierten, 7-jährigen Jungen im Pixar-ähnlichen Cartoon-Stil mit dem Titel „The Boy\". Das Sheet zeigt Frontal-, Seiten- und Rückenansichten, mehrere Gesichtsausdrücke (lachend, überrascht, nachdenklich, traurig), Full-Body-Posen (rennend, jubelnd, Karte lesend, sitzend) sowie Detail-Closeups von Shirt, Schuhen, Shorts und Haaren. Der Charakter hat zerzaustes braunes Haar, große braune Augen, trägt ein lila T-Shirt mit Weltraumhund-Print, khakifarbene Cargo-Shorts, gestreifte Socken und rote Sneaker.','[\"character-sheet\", \"cartoon-junge\", \"world-built\", \"pixar-stil\", \"lila-shirt\", \"7-jahre\", \"abenteuer\", \"reference-sheet\"]','2026-05-07 13:25:18','2026-05-08 10:47:07',4,1,'frontal portrait','Lila T-Shirt mit Weltraumhund-Aufdruck, khakifarbene Cargo-Shorts, blau-weiß gestreifte Socken, rote Schnürschuhe (Converse-Stil)','neutraler cremefarbener Hintergrund (Character-Sheet-Layout)','playful','[\"#7B5EA7\", \"#C68642\", \"#8B6914\"]','f2cfc4a7d6bd9c41fdfc8902ee09c37405f559d41c1e6010fc16fbd32b683747',NULL,1,72,'approved','[{\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"expression_laughing\", \"ageRange\": \"7\", \"description\": \"Der Junge mit weit geöffnetem Mund und strahlendem Lachen, Gesichts-Nahaufnahme.\"}, {\"axis\": \"pose\", \"mood\": \"surprised\", \"name\": \"expression_surprised\", \"ageRange\": \"7\", \"description\": \"Der Junge mit aufgerissenem Mund und großen Augen, Gesichts-Nahaufnahme, Ausdruck totaler Überraschung.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"expression_smiling\", \"ageRange\": \"7\", \"description\": \"Der Junge mit breitem, entspanntem Lächeln, Gesichts-Nahaufnahme, fröhlich-zufriedener Ausdruck.\"}, {\"axis\": \"pose\", \"mood\": \"sad\", \"name\": \"expression_sad\", \"ageRange\": \"7\", \"description\": \"Der Junge mit hängenden Mundwinkeln und unsicherem Blick, Gesichts-Nahaufnahme, traurig-besorgter Ausdruck.\"}, {\"axis\": \"pose\", \"mood\": \"neutral\", \"name\": \"view_side\", \"ageRange\": \"7\", \"description\": \"Der Junge in Seitenansicht (Profil nach links), Ganzkörper, neutraler Stand.\"}, {\"axis\": \"pose\", \"mood\": \"neutral\", \"name\": \"view_back\", \"ageRange\": \"7\", \"description\": \"Der Junge in Rückenansicht mit Händen in den Hosentaschen, Ganzkörper.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"pose_running\", \"ageRange\": \"7\", \"description\": \"Der Junge in voller Laufbewegung, lachend, Beine und Arme weit ausgestreckt.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"pose_cheering\", \"ageRange\": \"7\", \"description\": \"Der Junge jubelt mit beiden Armen in der Luft, breites Lachen, voller Begeisterung.\"}, {\"axis\": \"pose\", \"mood\": \"neutral\", \"name\": \"pose_map_reading\", \"ageRange\": \"7\", \"description\": \"Der Junge hält eine aufgefaltete Karte in beiden Händen und liest sie konzentriert, stehend.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"pose_sitting\", \"ageRange\": \"7\", \"description\": \"Der Junge sitzt am Boden mit verschränkten Armen und einem verspielten Grinsen.\"}]'),(12,'magnific_create-character-sheet-fo_2924197250','familie',NULL,'assets/uploads/1778160318864-magnific_create-character-sheet-fo_2924197250_0ec48491.png','/manus-storage/assets/uploads/1778160318864-magnific_create-character-sheet-fo_2924197250_0ec48491.png','Offizielles Character-Sheet eines animierten Jungen namens „The Boy\" (Alter 8, Rolle: Adventurer). Das Sheet zeigt Dreipunkt-Standansichten (Front, Seite, Rücken), sechs Gesichtsausdrücke (fröhlich, lachend, überrascht, traurig, wütend, schreiend), Detail-Crops (Auge, Ohr, Haare, Dino-T-Shirt-Print) sowie Action-Posen (rennend, springend, mit Lupe). Der Charakter trägt ein lila T-Shirt mit Dinosaurier-Aufdruck, blaue Jeans-Shorts, weiße Socken und rote Sneaker; die Haare sind struppig hellbraun.','[\"character sheet\", \"the boy\", \"animiert\", \"junge\", \"abenteurer\", \"dino-shirt\", \"expressions\", \"action poses\"]','2026-05-07 13:25:30','2026-05-08 10:46:55',4,1,'frontal portrait','Lila T-Shirt mit Dinosaurier-Print, blaue Jeans-Shorts, weiße Socken, rote Schnürschuhe','neutraler cremefarbener Hintergrund (Character-Sheet-Layout)','playful','[\"#7B52A6\", \"#C8843A\", \"#4A7ABF\"]','4705a74b30c649ed7c47a219f75c404c9acaf55b52c0ffc864f14548d7ac1e25',NULL,1,82,'approved',NULL),(13,'magnific_create-character-sheet-fo_2925365581','familie',NULL,'assets/uploads/1778160331052-magnific_create-character-sheet-fo_2925365581_f495ff82.png','/manus-storage/assets/uploads/1778160331052-magnific_create-character-sheet-fo_2925365581_f495ff82.png','Offizielles Character Sheet des fiktiven Jungen „The Boy\" im Cartoon-/Pixar-Stil auf cremefarbenem Papiergrund. Es zeigt eine Ganzkörper-Hauptpose, sechs beschriftete Gesichtsausdrücke (Happy, Excited, Surprised, Cheeky, Thinking, Laughing), ein 360°-Turnaround in vier Ansichten sowie Accessoires (Rucksack, Taschenlampe, Notizbuch, Kompass). Der Junge trägt ein lila Dinosaurier-T-Shirt, khakifarbene Cargo-Shorts, weiße Sportsocken und blaue Sneaker; sein Haar ist struppig hellbraun.','[\"character sheet\", \"the boy\", \"cartoon\", \"world-built\", \"turnaround\", \"expressions\", \"abenteuer\", \"kinderfigur\"]','2026-05-07 13:25:41','2026-05-08 10:46:53',4,1,'frontal portrait','Lila Dinosaurier-T-Shirt, khakifarbene Cargo-Shorts, weiße Sportsocken, blaue Schnürschuhe','neutraler cremefarbener Papier-Hintergrund (Character-Sheet-Layout)','playful','[\"#7b5ea7\", \"#c8a878\", \"#4a7abf\"]','479112f521b190ef5d98690345150c0c384f022408d3f1b9beb41b231075ca0d',NULL,1,82,'approved',NULL),(14,'magnific_create-variations-of-the-_2930899876','stil-referenz',NULL,'assets/uploads/1778164063349-magnific_create-variations-of-the-_2930899876_77412a0e.png','/manus-storage/assets/uploads/1778164063349-magnific_create-variations-of-the-_2930899876_77412a0e.png','Vollständiges Brand-Style-Sheet für das Projekt „Kinder, Chaos und kein Plan\" von KlareKante.berlin. Das Sheet umfasst Hauptlogo sowie alternative Logo-Varianten (Kreis, Badge, Sprechblase, Monogramm „KC\"), eine Farbpalette mit fünf Farben plus Creme, Typografie-Variationen, illustrierte Charaktere (Mädchen, Junge, Mops, Roboter), Icon-Assets, Website-Elemente und Hintergrundtexturen. Der Gesamtstil ist kindlich-fröhlich mit handgezeichnet wirkendem Lettering und cartoon-ähnlichen 3D-Illustrationen.','[\"brand-sheet\", \"logo-varianten\", \"farbpalette\", \"typografie\", \"illustration\", \"kinder\", \"chaos\", \"KlareKante\"]','2026-05-07 14:27:54','2026-05-07 14:27:54',NULL,0,'logo','n/a','Brand Style Guide / weißer/cremefarbener Hintergrund','playful','[\"#1E4A7A\", \"#C0392B\", \"#F2C97D\"]','250e37a192186240465fc9f70e853604525941cd76d87808367b21ab0359cb6f',NULL,1,97,'approved',NULL),(16,'magnific_create-variations-of-the-_2930941896','stil-referenz',NULL,'assets/uploads/1778164355889-magnific_create-variations-of-the-_2930941896_848bda94.png','/manus-storage/assets/uploads/1778164355889-magnific_create-variations-of-the-_2930941896_848bda94.png','Ein umfassendes Brand-Style-Guide-Sheet für den Eltern-Blog bzw. die Marke „Kinder, Chaos und kein Plan\" (KlareKante.berlin). Das Sheet zeigt Logo-Variationen (verschiedene Layouts und Stile), Farbvarianten (Navy, Rot, Creme, Senf, Hellblau, Olivgrün), Typografie-Variationen sowie Assets & Elemente (Icons, Sprechblasen, Sticker, Tier-Illustrationen eines Hundes, einer Katze, eines Mops und eines Mini-Roboters). Im Anwendungsbeispiel sind Desktop- und Mobile-Mockups sowie eine chaotische Familienszene mit Vater und springenden Kindern zu sehen.','[\"brand-guide\", \"logo-variationen\", \"farbpalette\", \"typografie\", \"stil-referenz\", \"elternblog\", \"KlareKante.berlin\", \"assets\"]','2026-05-07 14:32:46','2026-05-07 14:32:46',NULL,0,'logo','k.A. (kein Charakter im Vordergrund)','Brand Style Guide / Design-Sheet','playful','[\"#1b3a6b\", \"#c0392b\", \"#f5f0e8\"]','49a9a0ea00ccff662840d2381639f90a1ec2032d5e57486de26d1e5264818844',NULL,1,92,'approved',NULL),(17,'magnific_create-variations-of-the-_2930941903','stil-referenz',NULL,'assets/uploads/1778164367061-magnific_create-variations-of-the-_2930941903_0a449521.png','/manus-storage/assets/uploads/1778164367061-magnific_create-variations-of-the-_2930941903_0a449521.png','Ein vollständiges Brand-Style-Sheet für den Instagram-Auftritt „Kinder, Chaos und kein Plan\" (KlareKante.berlin). Es zeigt neun Logo-Variationen in verschiedenen Farb- und Formkombinationen, eine Farbpalette mit sechs Hex-Werten, Typografie-Varianten sowie Design-Elemente wie Kinder-Zeichnungen, Toilettenpapier, eine „DAD FUEL\"-Tasse und eine illustrierte Szene mit einem überforderten Vater, zwei chaotischen Kindern, einem Mops und weiteren Requisiten.','[\"style-guide\", \"branding\", \"logo-varianten\", \"farbpalette\", \"typografie\", \"kinder-chaos\", \"KlareKante.berlin\", \"design-sheet\"]','2026-05-07 14:32:56','2026-05-07 14:32:56',NULL,0,'logo','keine Person im Fokus','beige Hintergrund, flaches Layoutdesign / Brand-Sheet','chaotic','[\"#1E3A5F\", \"#C0392B\", \"#E6D0B3\"]','85f78d294b6fbeb213bd8b38ae9f0167b9c398bb5a823556bbba113fa1fb5613',NULL,1,92,'approved',NULL),(18,'mama/magnific_create-character-sheet-fo_2924191558','familie',NULL,'assets/familie/a6d241962a78-magnific_create-character-sheet-fo_2924191558_74d0986b.png','/manus-storage/assets/familie/a6d241962a78-magnific_create-character-sheet-fo_2924191558_74d0986b.png','Vollständiges animiertes Character-Sheet einer Cartoon-Frau mit kurzen, blonden Haaren, die als „Mom – Adventure Co-Pilot\" bezeichnet wird. Die Figur trägt ein schwarzes Tank-Top, olivgrüne Cargo-Hosen, braune Converse-Sneaker sowie Goldring-Ohrringe, mehrere Armbänder und eine Halskette. Das Sheet zeigt Haupt-Pose (frontal, daumen-hoch), sechs Gesichtsausdrücke (Excited, Laughing, Surprised, Focused, Worried, Proud), ein Turnaround (vorne, Seite, hinten) sowie Ausrüstungsgegenstände wie Lucky Necklace, Bracelets, Kaffeebecher „Adventure Fuel\" und eine Landkarte.','[\"character-sheet\", \"mama\", \"cartoon\", \"adventure\", \"blonde\", \"cargo-hose\", \"familie\", \"turnaround\"]','2026-05-07 15:04:31','2026-05-08 10:46:46',5,1,'frontal portrait','Schwarzes Tank-Top, olivgrüne Cargo-Hose mit Umschlag, braune Converse-Sneaker, Ledergürtel, Goldring-Ohrringe, Armbänder, Halskette','Neutraler cremefarbener Hintergrund (Character-Sheet-Layout)','happy','[\"#2b2b2b\", \"#6b7a3e\", \"#c8a96e\"]','a6d241962a780f5869df897a1ecd312e3f3007e0bba5d9e841b6989dc18f2ad0','klarekante-style/mama/magnific_create-character-sheet-fo_2924191558.png',1,97,'approved','[{\"axis\": \"pose\", \"mood\": \"excited\", \"name\": \"expression_excited\", \"description\": \"Mom mit weit aufgerissenem Mund und strahlenden Augen – freudige Begeisterung.\"}, {\"axis\": \"pose\", \"mood\": \"happy\", \"name\": \"expression_laughing\", \"description\": \"Mom lacht herzhaft mit geschlossenem Auge und breitem Grinsen.\"}, {\"axis\": \"pose\", \"mood\": \"surprised\", \"name\": \"expression_surprised\", \"description\": \"Mom mit aufgerissenen Augen und offenem Mund – überwältigte Überraschung.\"}, {\"axis\": \"pose\", \"mood\": \"focused\", \"name\": \"expression_focused\", \"description\": \"Mom schaut konzentriert auf eine aufgeklappte Landkarte in ihren Händen.\"}, {\"axis\": \"pose\", \"mood\": \"worried\", \"name\": \"expression_worried\", \"description\": \"Mom beißt sich nervös auf den Finger, Stirn leicht gerunzelt – besorgte Miene.\"}, {\"axis\": \"pose\", \"mood\": \"proud\", \"name\": \"expression_proud\", \"description\": \"Mom lächelt selbstzufrieden mit leicht angehobenem Kinn – stolzer Gesichtsausdruck.\"}]'),(19,'mama/magnific_create-character-sheet-fo_2925369606','familie',NULL,'assets/familie/74f53d357c46-magnific_create-character-sheet-fo_2925369606_3603fcfe.png','/manus-storage/assets/familie/74f53d357c46-magnific_create-character-sheet-fo_2925369606_3603fcfe.png','Vollständiges Charakter-Referenzblatt einer animierten Mutter-Figur im Pixar/Disney-3D-Stil mit blondem Hochsteckdutt, Gold-Creolen und ausdrucksstarken braunen Augen. Das Sheet zeigt Drehtansichten (frontal, Seite, Rücken), mehrere Gesichtsausdrücke sowie fünf Outfit-Varianten (Road Trip, Hiking Day, Beach Day, Road Dinner, Cozy Night) inklusive Accessoire-Details und Farbpalette. Die Figur wirkt energetisch, optimistisch und warmherzig.','[\"charakter-sheet\", \"mama\", \"familie\", \"pixar-stil\", \"animiert\", \"outfit-varianten\", \"referenz\", \"3D-cartoon\"]','2026-05-07 15:04:32','2026-05-08 10:46:38',5,1,'frontal portrait','Schwarzes Tank-Top, Olive-Hemd um die Hüften gebunden, blaue Jeans (gerollt), braune Schnürstiefel – plus vier weitere Outfit-Varianten (Casual, Hiking, Beach, Dinner, Cozy)','neutraler cremefarbener Hintergrund (Character-Sheet-Layout)','happy','[\"#e8c97a\", \"#2c2c2c\", \"#6b8e5a\"]','74f53d357c4609233790b5cb9db3428c1b26851f54d4b057a952baaa03ebf289','klarekante-style/mama/magnific_create-character-sheet-fo_2925369606.png',1,98,'approved','[{\"ax