INSERT INTO `characters` VALUES (1,'Toni','[\"Papa\", \"Vater\", \"Dad\", \"mein Vater\", \"Adventure Captain\"]','family',NULL,NULL,1,NULL,'2026-05-07 10:46:05','2026-05-07 10:46:05'),(3,'Lily','[\"Tochter\", \"meine Tochter\", \"MÃ¤dchen\", \"Lily\", \"Adventure Enthusiast\"]','world-built',NULL,NULL,10,NULL,'2026-05-07 13:23:21','2026-05-07 15:03:30'),(4,'The Boy','[\"Sohn\", \"mein Sohn\", \"Junge\", \"Der Junge\", \"Adventure Boy\", \"The Boy\"]','world-built',NULL,NULL,11,NULL,'2026-05-07 13:25:18','2026-05-07 15:03:30'),(5,'Mama','[\"Mutter\", \"Mom\", \"Adventure Co-Pilot\", \"Mama\"]','family',NULL,NULL,18,NULL,'2026-05-07 15:04:31','2026-05-07 15:04:31');
